<template><textarea :data-testid="textareaTestId" v-model="model" :placeholder="placeholder" class="w-full h-full min-h-64 resize-none rounded-xl border border-slate-200 p-4 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/20" /></template>
<script setup>import {computed} from 'vue';const p=defineProps({modelValue:{type:String,default:''},placeholder:String,height:{type:String,default:'100%'},textareaTestId:{type:String,default:'markdown-editor'}});const e=defineEmits(['update:modelValue']);const model=computed({get:()=>p.modelValue,set:v=>e('update:modelValue',v)});</script>
